function validate([equations]) {
  if (!Array.isArray(equations) || equations.length < 1 || equations.length > 500) return 'equations needs 1 to 500 strings.';
  if (equations.some(e => typeof e !== 'string' || !/^[a-z][=!]=[a-z]$/.test(e))) return 'Each equation looks like "a==b" or "a!=b" with lowercase letters.';
  return null;
}

