function equationsPossible(equations) {
  // Give every letter its own label, then keep copying the smaller label across each "=="
  // until nothing changes; letters that must be equal end up sharing a label.
  const label = {};
  for (const e of equations) { label[e[0]] = e[0]; label[e[3]] = e[3]; }
  let changed = true;
  while (changed) {
    changed = false;
    for (const e of equations) {
      if (e[1] !== '=') continue;
      const low = label[e[0]] < label[e[3]] ? label[e[0]] : label[e[3]];
      if (label[e[0]] !== low || label[e[3]] !== low) { label[e[0]] = low; label[e[3]] = low; changed = true; }
    }
  }
  return equations.every(e => e[1] === '=' || label[e[0]] !== label[e[3]]);
}

