function generate(rand, size) {
  const pick = (k) => Math.floor(rand() * k);
  const m = size === 'large' ? 400 + pick(101) : 1 + pick(8);
  const poolSize = size === 'large' ? 2 + pick(25) : (rand() < 0.15 ? 1 : 2 + pick(5));
  const start = pick(27 - poolSize);
  const pool = Array.from({ length: poolSize }, (_, i) => String.fromCharCode(97 + start + i));
  // Split the letters into groups: "==" stays inside a group and "!=" crosses groups,
  // so the system is satisfiable until one relation is corrupted below.
  const groups = 1 + pick(poolSize);
  const group = new Map(pool.map(letter => [letter, pick(groups)]));
  const equalShare = rand();
  const equations = [];
  for (let i = 0; i < m; i++) {
    const x = pool[pick(poolSize)];
    if (rand() < equalShare) {
      const mates = pool.filter(letter => group.get(letter) === group.get(x));
      equations.push(`${x}==${mates[pick(mates.length)]}`);
    } else {
      const others = pool.filter(letter => group.get(letter) !== group.get(x));
      equations.push(others.length ? `${x}!=${others[pick(others.length)]}` : `${x}==${x}`);
    }
  }
  if (rand() < 0.6) {
    const i = pick(m), x = pool[pick(poolSize)];
    const mates = pool.filter(letter => group.get(letter) === group.get(x));
    equations[i] = rand() < 0.5 ? `${x}!=${mates[pick(mates.length)]}` : equations[i].replace('!=', '==');
  }
  return [equations];
}
